// src/App.js
import React from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route
} from 'react-router-dom';
import Background from './components/Background';
import { Navbar } from './components/Navbar'; // Import your Navbar component
import About from './components/pages/About'; // Make sure you have an About component
import { Resume } from './components/pages/Resume'; // Make sure you have a Resume component
import { Projects } from './components/pages/Projects'; // Make sure you have a Projects component
import ContactMe from './components/pages/ContactMe'; // Make sure you have a ContactMe component
import './App.css';

function App() {
  return (
    <Router>
      <div className="App">
        <Navbar />
        <Background />
        <Routes>
          <Route path="/" element={<About />} />
          <Route path="/about" element={<About />} />
          <Route path="/resume" element={<Resume />} />
          <Route path="/projects" element={<Projects />} />
          <Route path="/contact" element={<ContactMe />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
